mapper.update:
UPDATE tc_user_group_member
   SET user_pk    = #{m.userPk},
       group_id   = #{m.groupId},
       granted_at = COALESCE(#{m.grantedAt, typeHandler=com.nori.tc.db.mybatis.common.typehandler.OffsetDateTimeTypeHandler}, granted_at),
       granted_by = #{m.grantedBy}
 WHERE ugm_key    = #{m.ugmKey}

mapper.select:
SELECT 
  FROM tc_user_group_member
 WHERE user_pk = #{userPk}
   AND group_id = #{groupId}

SELECT 
  FROM tc_user_group_member
 WHERE user_pk = #{userPk}
 ORDER BY group_id ASC, ugm_key ASC

    LIMIT #{limit} OFFSET #{offset}

SELECT 
  FROM tc_user_group_member
 WHERE group_id = #{groupId}
 ORDER BY user_pk ASC, ugm_key ASC

    LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE FROM tc_user_group_member
 WHERE user_pk = #{userPk}
   AND group_id = #{groupId}
